using System;using System.Reflection;using Ossastra.CharacterCore;
class Tests{static int n;static void Check(bool b,string m){if(!b)throw new Exception(m);n++;}static void Main(){
var t=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.StaminaState");Check(t!=null,"missing per-body stamina authority");dynamic a=Activator.CreateInstance(t,new object[]{100d,.5d,20d});dynamic b=Activator.CreateInstance(t,new object[]{100d,.5d,20d});var id=Guid.NewGuid();Check(a.TrySpend(id,22d,0d)&&a.Current==78d,"accepted fee");Check(!a.TrySpend(id,22d,0d)&&a.Current==78d,"same token no duplicate fee");Check(b.Current==100d,"independent actor");Check(!a.TrySpend(Guid.NewGuid(),100d,0d)&&a.Current==78d,"insufficient rejects");a.Tick(.4d,true);Check(a.Current==78d,"delay");a.Tick(.6d,false);Check(a.Current==78d,"active does not regen");a.Tick(.8d,true);Check(Math.Abs((double)a.Current-82)<.001,"idle regen");a.Tick(.8d,true);Check(a.Current==82d,"paused same clock");a.Restore();Check(a.Current==100d,"same state restore");
var d=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.DodgeState");Check(d!=null,"missing dodge clock");dynamic dodge=Activator.CreateInstance(d,new object[]{.45d,.12d,.32d});Check(dodge.TryStart(0d),"dodge starts");Check(!dodge.IsInvulnerable,"startup vulnerable");dodge.Tick(.12d);Check(dodge.IsInvulnerable,"window start inclusive");dodge.Tick(.32d);Check(!dodge.IsInvulnerable,"window end exclusive");dodge.Tick(.45d);Check(!dodge.IsActive,"ends");Check(dodge.TryStart(1d),"new dodge");dodge.Cancel();Check(!dodge.IsActive&&!dodge.IsInvulnerable,"cancel clears");Console.WriteLine(n+" stamina/dodge contracts passed");}}
